/* ===== v4：咪姬 = C 款原圖 Real-ESRGAN 放大 → 100 色量化 → vtracer 全彩描圖（純 path，無點陣／filter） ===== */
const PIVOT={head:'300 338',tail:'300 690',paw:'300 430',body:'300 690',sign:'300 430',tile:'300 400',earL:'167 118',earR:'431 116',eyes:'300 241'};
const MAT=`matrix(${TR.K} 0 0 ${TR.K} ${TR.TX} ${TR.TY})`;
let PS=null;
function P(i){if(!PS)PS=new Array(TR.P.length);if(!PS[i]){const s=TR.P[i],k=s.indexOf(' ');PS[i]=`<path fill="${TR.PAL[+s.slice(0,k)]}" d="${s.slice(k+1)}"/>`;}return PS[i];}
function paths(list){let o='';if(list){for(const i of list)o+=P(i);}else{for(let i=0;i<TR.P.length;i++)o+=P(i);}return `<g transform="${MAT}">${o}</g>`;}
const MOUTH=TR.P.length<6000?`<path fill="#5B3B33" d="${TR.mouth}"/>`:'';  /* lite 版補一條清楚的嘴線 */
const EYE={L:[229,241],R:[361,240]};
function defs(id){
  let s='';for(const k of ['body','head','earL','earR','eyes','paw'])s+=`<clipPath id="${id}c_${k}"><path clip-rule="evenodd" d="${TR.clip[k]}"/></clipPath>`;
  for(const n of ['L','R']){const c=TR.eye[n],[x,y]=EYE[n],o=n==='L'?-1:1;
    s+=`<linearGradient id="${id}e${n}" gradientUnits="userSpaceOnUse" x1="${x+o*44}" y1="0" x2="${x-o*44}" y2="0"><stop offset="0" stop-color="${c.out}"/><stop offset="1" stop-color="${c.in}"/></linearGradient>`;
    s+=`<linearGradient id="${id}v${n}" gradientUnits="userSpaceOnUse" x1="0" y1="${y-44}" x2="0" y2="${y+44}"><stop offset="0" stop-color="${c.top}"/><stop offset=".45" stop-color="${c.top}" stop-opacity="0"/><stop offset=".6" stop-color="${c.bot}" stop-opacity="0"/><stop offset="1" stop-color="${c.bot}"/></linearGradient>`;
    s+=`<radialGradient id="${id}g${n}"><stop offset=".74" stop-color="#fff"/><stop offset="1" stop-color="#000"/></radialGradient><mask id="${id}m${n}" maskUnits="userSpaceOnUse" x="${x-60}" y="${y-60}" width="120" height="120"><ellipse cx="${x}" cy="${y}" rx="47" ry="46" fill="url(#${id}g${n})"/></mask>`;}
  s+=`<linearGradient id="${id}pink" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFA9BC"/><stop offset="1" stop-color="#F27C99"/></linearGradient>`;
  s+=`<clipPath id="${id}eHalf"><rect x="150" y="150" width="300" height="91"/></clipPath>`;
  return s;}
/* 閉眼／半瞇眼：毛色補丁蓋在原眼上（只有眨眼時、或 smug／sleepy 表情才看得到） */
function eyePatch(id,mode){let s='';
  for(const n of ['L','R']){const [x,y]=EYE[n],o=n==='L'?-1:1;
    const patch=`<g mask="url(#${id}m${n})"><ellipse cx="${x}" cy="${y}" rx="47" ry="46" fill="url(#${id}e${n})"/><ellipse cx="${x}" cy="${y}" rx="47" ry="46" fill="url(#${id}v${n})"/></g>`;
    if(mode==='half'){s+=`<g clip-path="url(#${id}eHalf)">${patch}</g><path d="M${x-31} ${y+1}C${x-14} ${y-4} ${x+14} ${y-4} ${x+31} ${y+1}" fill="none" stroke="#3E2B22" stroke-width="4.6" stroke-linecap="round"/><path d="M${x+o*30} ${y+1}L${x+o*40} ${y-5}" stroke="#3E2B22" stroke-width="3.5" stroke-linecap="round"/>`;}
    else{s+=patch+`<path d="M${x-27} ${y+2}C${x-14} ${y+14} ${x+14} ${y+14} ${x+27} ${y+2}" fill="none" stroke="#3E2B22" stroke-width="4.6" stroke-linecap="round"/><path d="M${x+o*25} ${y+5}L${x+o*36} ${y+1}" stroke="#3E2B22" stroke-width="3.5" stroke-linecap="round"/>`;}}
  return s;}
